static int hpb_varint(HPB*b,uint64_t*v){uint64_t x=0;int sh=0;while(b->pos<b->n&&sh<70){unsigned char c=b->p[b->pos++];x|=((uint64_t)(c&127))<<sh;if(!(c&128)){*v=x;return 1;}sh+=7;}return 0;}
