static void onnx_put_var(DBuf*b,uint64_t x){unsigned char z[10];int n=0;do{z[n]=(unsigned char)(x&127);x>>=7;if(x)z[n]|=128;n++;}while(x);dbuf_putn(b,(const char*)z,(size_t)n);}
static void onnx_key(DBuf*b,int f,int w){onnx_put_var(b,((uint64_t)f<<3)|w);}
static void onnx_var(DBuf*b,int f,uint64_t x){onnx_key(b,f,0);onnx_put_var(b,x);}
static void onnx_bytes(DBuf*b,int f,const void*p,size_t n){onnx_key(b,f,2);onnx_put_var(b,n);dbuf_putn(b,p,n);}
static void onnx_str(DBuf*b,int f,const char*s){onnx_bytes(b,f,s,strlen(s));}
static void onnx_tensor(DBuf*b,const char*name,int d0,int d1,const double*src,int rows,int cols,int transpose){DBuf t={0},raw={0};for(int i=0;i<rows*cols;i++){float x=(float)(transpose?src[(i%rows)*cols+i/rows]:src[i]);dbuf_putn(&raw,(const char*)&x,4);}onnx_str(&t,8,name);onnx_var(&t,2,1);onnx_var(&t,1,(uint64_t)d0);onnx_var(&t,1,(uint64_t)d1);onnx_bytes(&t,9,raw.d,raw.n);onnx_bytes(b,5,t.d,t.n);if(raw.d)free(raw.d);if(t.d)free(t.d);}
